"""Hand an outside agent's changes-requested verdict summary to the repair worker.

Same rule as factory-outside-verdict.cjs: the owner's account (a human login,
never a bot) ends a review or summary comment with ``Verdict: ...`` as its
last non-empty line outside code fences, with a ``Model:`` line. A review binds
to its commit; a comment binds to a head SHA (7+ characters) it names.
"""

from __future__ import annotations

import json
import re
import sys
from collections.abc import Iterable, Mapping
from pathlib import Path
from typing import Any

VERDICT_LINE = re.compile(r"Verdict: (changes-requested|approve)[ \t]*")
MODEL_LINE = re.compile(r"Model:[ \t]*\S")
FENCE = re.compile(r"[ \t]*(```|~~~)")
RULE = re.compile(r"[ \t]*-{3,}[ \t]*")
TOOL_FOOTER = re.compile(r"_Generated by .+_[ \t]*")
SHA = re.compile(r"\b[0-9a-f]{7,40}\b", re.IGNORECASE)
LIMIT = 7000


def _lines(body: str) -> list[tuple[str, bool]]:
    fenced = False
    lines: list[tuple[str, bool]] = []
    for line in body.splitlines():
        if FENCE.match(line):
            fenced = not fenced
            lines.append((line, True))
        elif line.strip():
            lines.append((line, fenced))
    if (
        len(lines) >= 2
        and not lines[-1][1]
        and not lines[-2][1]
        and TOOL_FOOTER.fullmatch(lines[-1][0])
        and RULE.fullmatch(lines[-2][0])
    ):
        del lines[-2:]
    return lines


def verdict_of(body: str) -> str | None:
    lines = _lines(body or "")
    if not lines or lines[-1][1]:
        return None
    match = VERDICT_LINE.fullmatch(lines[-1][0])
    if match is None:
        return None
    return match.group(1) if any(not f and MODEL_LINE.match(line) for line, f in lines) else None


def names_head(body: str, head: str) -> bool:
    wanted = head.lower()
    return bool(wanted) and any(wanted.startswith(t.lower()) for t in SHA.findall(body or ""))


def owner_authored(row: Mapping[str, Any], owner: str) -> bool:
    user = row.get("user") or {}
    login = str(user.get("login") or "")
    if not login or user.get("type") == "Bot" or login.endswith("[bot]"):
        return False
    return login.lower() == owner.lower() or row.get("author_association") == "OWNER"


def latest(
    reviews: Iterable[Mapping[str, Any]],
    comments: Iterable[Mapping[str, Any]],
    *,
    head: str,
    owner: str,
    marker_prefix: str,
) -> dict[str, Any] | None:
    rows = [(r, str(r.get("submitted_at") or "")) for r in reviews if r.get("commit_id") == head]
    rows += [
        (c, str(c.get("created_at") or ""))
        for c in comments
        if names_head(str(c.get("body") or ""), head)
    ]
    found: dict[str, Any] | None = None
    for row, at in rows:
        body = str(row.get("body") or "")
        if not owner_authored(row, owner) or f"{marker_prefix}-factory-" in body:
            continue
        verdict = verdict_of(body)
        if verdict and (found is None or at >= found["at"]):
            found = {"verdict": verdict, "at": at, "body": body, "url": row.get("html_url") or ""}
    return found


def findings_section(found: Mapping[str, Any] | None) -> str:
    if found is None or found["verdict"] != "changes-requested":
        return ""
    body = str(found["body"])
    if len(body) > LIMIT:
        body = body[:LIMIT] + "\n[... truncated; read the full summary on GitHub ...]"
    return (
        "\n## Outside agent review: changes requested at this head\n"
        f"The owner account posted this outside review summary ({found['url']}). "
        "Its line comments are in the unresolved review threads above. Fix every "
        "blocking finding it names, or answer it with evidence.\n\n" + body + "\n"
    )


def _rows(path: str) -> list[Mapping[str, Any]]:
    data = json.loads(Path(path).read_text() or "[]")
    return [row for row in data if isinstance(row, dict)] if isinstance(data, list) else []


def main(argv: list[str]) -> int:
    reviews, comments, head, owner, prefix = argv
    found = latest(_rows(reviews), _rows(comments), head=head, owner=owner, marker_prefix=prefix)
    sys.stdout.write(findings_section(found))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
